using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
namespace NightLens {
static class WeatherTests {
 static IEnumerable<Control> Walk(Control root){foreach(Control child in root.Controls){yield return child;foreach(var nested in Walk(child))yield return nested;}}
 static void Shot(Form form,string path){form.Show();Application.DoEvents();using(var image=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(path);}}
 public static void Run(Forecast f,DateTime now,string[] args,List<string> log){Action<bool,string> check=(ok,message)=>{if(!ok)throw new Exception(message);log.Add("PASS: "+message);};var s=new Settings{WindowsLocation=false};var n=new Night(s,f,now);var w=new ObservingWeather(s,f,n);check(w.DarkStart.HasValue&&w.DarkEnd>w.DarkStart&&w.Hours.Count>5,"Conditions cover the computed astronomical dark window");check(w.SunEvent(CosineKitty.Direction.Set,0)<w.SunEvent(CosineKitty.Direction.Set,-6)&&w.SunEvent(CosineKitty.Direction.Set,-6)<w.SunEvent(CosineKitty.Direction.Set,-12)&&w.SunEvent(CosineKitty.Direction.Set,-12)<w.DarkStart,"Sunset, civil dusk, nautical dusk and astronomical dusk are ordered");check(w.DarkEnd<w.SunEvent(CosineKitty.Direction.Rise,-12)&&w.SunEvent(CosineKitty.Direction.Rise,-12)<w.SunEvent(CosineKitty.Direction.Rise,-6)&&w.SunEvent(CosineKitty.Direction.Rise,-6)<w.SunEvent(CosineKitty.Direction.Rise,0),"Astronomical dawn, nautical dawn, civil dawn and sunrise are ordered");check(w.Hours.All(h=>h.Utc<w.DarkEnd&&h.Utc.AddHours(1)>w.DarkStart),"Hourly table includes only model hours overlapping darkness");check(w.Moonless.All(window=>window.Item1>=n.Dark.First()&&window.Item2<=w.DarkEnd&&n.Altitude(CosineKitty.Body.Moon,window.Item1.AddTicks((window.Item2-window.Item1).Ticks/2))<0),"Moon-free intervals are constrained to darkness and Moon below horizon");check(Math.Abs(n.Altitude(CosineKitty.Body.Sun,w.DarkStart.Value)+18)<.01&&n.Dark.First()>=w.DarkStart&&n.Dark.First()<w.DarkStart.Value.AddMinutes(10),"Precise and sampled darkness use the same geometric Sun-below-18-degree definition");check(w.Spread(5)=="9 °F"&&w.Temp(5)=="41 °F","Temperature differences convert without adding Fahrenheit's 32-degree offset");
 Func<Hour> clear=()=>new Hour{Utc=n.Start,Cloud=5,Rain=0,Wind=5,Gust=10,Temp=10,Dew=0};check(ObservingWeather.Evaluate(new[]{clear()}).Word=="GO","Clear, calm, dry hourly weather produces GO");var bad=clear();bad.Cloud=85;check(ObservingWeather.Evaluate(new[]{bad}).Word=="NO-GO","Heavy cloud produces NO-GO");bad=clear();bad.Cloud=54;check(ObservingWeather.Evaluate(new[]{bad}).Word=="MARGINAL","Broken cloud produces MARGINAL");bad=clear();bad.Rain=60;check(ObservingWeather.Evaluate(new[]{bad}).Word=="NO-GO","High rain chance prevents GO");bad=clear();bad.Wind=36;check(ObservingWeather.Evaluate(new[]{bad}).Word=="NO-GO","Strong wind prevents GO");bad=clear();bad.Dew=9;check(ObservingWeather.Evaluate(new[]{bad}).Word=="MARGINAL","Small dew-point margin raises a caution");bad=clear();bad.Humidity=95;check(ObservingWeather.Evaluate(new[]{bad}).Word=="MARGINAL","High humidity raises a planning caution");check(ObservingWeather.Evaluate(new[]{new Hour{Utc=n.Start}}).Word=="LIMITED DATA","Missing weather never becomes invented good conditions");bad=clear();bad.Cloud=100;bad.Gust=null;check(ObservingWeather.Evaluate(new[]{bad}).Word=="NO-GO","Known severe conditions remain NO-GO even if optional gust data is missing");
 var legacy=new Forecast();legacy.ParseWeather(File.ReadAllText(Path.Combine(Path.GetDirectoryName(Path.GetFullPath(args[4])),"weather-live-v3.json")));check(legacy.Hours.Count>72&&legacy.Hours.All(h=>!h.Gust.HasValue&&!h.LowCloud.HasValue),"Older forecast responses parse safely with optional fields absent");check(f.Hours.Any(h=>h.Gust.HasValue&&h.LowCloud.HasValue&&h.FeelsLike.HasValue&&h.Pressure.HasValue),"Expanded live forecast parses gusts, cloud layers, feels-like and pressure");check(f.Seeing.Any(h=>h.Transparency.HasValue),"7Timer atmospheric transparency is parsed separately from seeing");
var fallback=new ObservingWeather(s,new Forecast(),new Night(s,new Forecast(),now,new DateTime(2026,10,31)));var repeated=fallback.Hours.GroupBy(h=>s.Local(h.Utc)).Where(group=>group.Count()>1).First();check(repeated.Select(h=>fallback.HourLabel(h.Utc)).Distinct().Count()==2,"Repeated daylight-saving hours include distinct UTC offsets in the hourly table");
 string folder=Path.GetDirectoryName(args[3]);foreach(string mode in new[]{"Light","Dark","Night"}){Style.SetTheme(mode);using(var details=WeatherViews.Details(w)){Shot(details,Path.Combine(folder,mode+" conditions preview.png"));check(Walk(details).OfType<Label>().Any(l=>l.Text.Contains("CLOUD COVER"))&&Walk(details).OfType<Label>().Any(l=>l.Text.Contains("FULL CONDITION REPORT")),mode+" detailed conditions include metric cards and the full report");Walk(details).OfType<SectionButton>().Single(button=>button.Text=="Moon & darkness").PerformClick();Application.DoEvents();Shot(details,Path.Combine(folder,mode+" moon darkness preview.png"));check(Walk(details).OfType<Label>().Any(l=>l.Text=="MOON-FREE WINDOW")&&Walk(details).OfType<Label>().Any(l=>l.Text=="SUNRISE"),mode+" Moon page includes moon-free windows, twilight and solar events");}using(var hourly=WeatherViews.Hourly(w)){Shot(hourly,Path.Combine(folder,mode+" hourly table preview.png"));check(Walk(hourly).OfType<Label>().Any(l=>l.Text=="Dew point")&&Walk(hourly).OfType<Label>().Any(l=>l.Text=="Gust"),mode+" hourly table includes dew point, humidity, wind, gust and status");}}
 Style.SetTheme("Dark");using(var main=new MainForm(true)){main.LoadTest(f,now);main.Show();Application.DoEvents();var banner=Walk(main).OfType<ObservingBanner>().Single();bool opened=false;using(var close=new System.Windows.Forms.Timer{Interval=150}){close.Tick+=(a,b)=>{close.Stop();var details=Application.OpenForms.Cast<Form>().FirstOrDefault(form=>form.Text=="Observing conditions & darkness");if(details!=null){opened=true;details.Close();}};close.Start();typeof(Control).GetMethod("OnDoubleClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(banner,new object[]{EventArgs.Empty});}check(opened,"Double-clicking the observing-verdict banner opens detailed conditions and Moon information");}
 }
}
}
